testcase.system-out:
@import static example.JteContext.*

@param String greeting
@param String name
<h2>${greeting}, ${name}!</h2>

@import static example.JteContext.*
@import gg.jte.Content

@param Content bodyContent
@param String greeting
@param String name

<h2>${greeting} ${!isEmpty(name) ? ", " + name : ""}!</h2>
<p>${bodyContent}</p>

@import static example.JteContext.*

!{var hello = "Hello World!";}
${hello}

!{var content = @`
    @if(true)
        <p>Hello World</p>
    @else
        <p>Hello, false World</p>
    @endif
`;}
${content}

@import static example.JteContext.*

@param String greeting
@param String name
<h2>${greeting}, <fmt:formatDate value="name" pattern="yyyy"></fmt:formatDate>!</h2>

@import static example.JteContext.*

${localize("hello.world")}

!{var hello = localize("hello.world");}
${hello}

${localize("some.params", hello, "Param 2")}

!{var params = localize("some.params", hello, "Param 2");}
${params}

@if(5 > 0)
    <span class="text-md">
        ${localize("nested", localize("common.x", "Something"))}
    </span>
@endif

@import static example.JteContext.*
@import gg.jte.support.ForSupport
@import java.util.List

@param List rows

<div class="well content m-b-3">
    @for(var loop : ForSupport.of(rows))
        !{var row = loop.get();}
        <strong>${row.label}</strong>
        <strong>${loop.first}</strong>
        <strong>${loop.last}</strong>
        <strong>${loop.index}</strong>
    @endfor
</div>

