@import static example.JteContext.*

Hello include!

@param String greeting
@param String name
<h2>${greeting}, ${name}!</h2>

@import static example.JteContext.*

@param String greeting<%-- first param --%>
@param String name
<h2>${greeting}, ${name}!</h2>

@import static example.JteContext.*

@template.tag.my.simple(
    name = "Hello " + " Hola",
    greeting = "World"
)

@import static example.JteContext.*
@import example.FoodOption

@param FoodOption foodOption
@param boolean hangover = CHOOSE_DEFAULT_VALUE

<h4>
@if(foodOption == "Pizza")
    @if(hangover)
        Pizza is <b>a good choice to recover</b>!
        Prost!
    @else
        Pizza is <b>super yummy</b>!
        That's for sure!
    @endif
@elseif(foodOption == "Salad")
    Salad is <i>super healthy</i>!
@else
    Enjoy your ${foodOption} :-)
@endif

<%-- A one liner! --%>
@if(hangover)Hangover@elseNo hangover@endif
</h4>

@import static example.JteContext.*
@import java.util.List

@param List rows

<div class="well content m-b-3">
    @for(var row : rows)
        <div class="row m-b-2">
            <div class="col-sm-12 col-md-8">
                <p class="m-y-1">
                    <strong>${row.label}</strong>
                </p>
            </div>
        </div>
    @endfor
</div>

